```css
--shadow-none: none;
--shadow-sm: 0 1px 2px rgba(14, 30, 25, 0.06);   /* 입력·작은 카드 */
--shadow-md: 0 8px 24px rgba(14, 30, 25, 0.08);  /* 카드 hover */
